const path = require('path');
const fs = require('fs-extra');
const { execSync } = require('child_process');
const { default: ora } = require('ora');
const { default: chalk } = require('chalk');

const TEMPLATE_BASE = path.join(__dirname, '..', 'templates', 'base');
const INSTALL_PACKAGES = ['node-telegram-bot-api', 'dotenv', 'chalk'];

function formatTargetPath(target) {
  return target ? path.resolve(process.cwd(), target) : process.cwd();
}

function resolvePackageJson(targetPath) {
  return path.join(targetPath, 'package.json');
}

async function mergeScripts(targetPath, templateMeta, logger) {
  const packageJsonPath = resolvePackageJson(targetPath);
  let targetPackage = {};

  if (await fs.pathExists(packageJsonPath)) {
    targetPackage = await fs.readJson(packageJsonPath);
  } else {
    const defaultName = path.basename(targetPath) || 'vibe-coder-telegram-project';
    targetPackage = {
      name: defaultName,
      version: '1.0.0',
      description: 'Generated Telegram-based coding assistant',
      main: 'telegram/bot.js',
      scripts: {},
      license: 'MIT'
    };
  }

  targetPackage.scripts = targetPackage.scripts || {};
  const newScripts = templateMeta.scripts || {};

  Object.keys(newScripts).forEach((scriptName) => {
    if (!targetPackage.scripts[scriptName]) {
      targetPackage.scripts[scriptName] = newScripts[scriptName];
      logger.info(`Injected script: ${scriptName}`);
    } else {
      logger.warn(`Script already exists, skipping: ${scriptName}`);
    }
  });

  await fs.writeJson(packageJsonPath, targetPackage, { spaces: 2 });
}

function installDependencies(targetPath, logger) {
  logger.info('Installing required dependencies in target project...');
  execSync(`npm install --save ${INSTALL_PACKAGES.join(' ')}`, {
    cwd: targetPath,
    stdio: 'inherit'
  });
  logger.succeed('Dependencies installed.');
}

async function initProject(target) {
  const targetPath = formatTargetPath(target);
  const spinner = ora(`Initializing project at ${targetPath}`).start();

  try {
    await fs.ensureDir(targetPath);

    const templateMetaPath = path.join(TEMPLATE_BASE, 'package.vibe.json');
    const templateMeta = await fs.readJson(templateMetaPath);

    const telegramSource = path.join(TEMPLATE_BASE, 'telegram');
    const telegramDestination = path.join(targetPath, 'telegram');
    await fs.copy(telegramSource, telegramDestination, {
      overwrite: false,
      errorOnExist: false
    });

    const envSource = path.join(TEMPLATE_BASE, '.env.example');
    const envDestination = path.join(targetPath, '.env.example');
    if (!(await fs.pathExists(envDestination))) {
      await fs.copy(envSource, envDestination, { overwrite: false });
    }

    await mergeScripts(targetPath, templateMeta, {
      info: (message) => spinner.info(chalk.blue(message)),
      warn: (message) => spinner.warn(chalk.yellow(message)),
      succeed: (message) => spinner.succeed(chalk.green(message))
    });

    spinner.text = 'Installing packages and finalizing setup...';
    installDependencies(targetPath, {
      info: () => {},
      warn: () => {},
      succeed: () => {}
    });

    spinner.succeed('Telegram assistant scaffold created successfully.');
    console.log(chalk.green('Done!')); 
    console.log(chalk.blue('Next steps:'));
    console.log(`  1. cd ${target ? targetPath : '.'}`);
    console.log('  2. copy .env.example to .env and configure TELEGRAM_BOT_TOKEN and ALLOWED_CHAT_ID');
    console.log('  3. npm run telegram:start');
  } catch (error) {
    spinner.fail('Failed to initialize project.');
    throw error;
  }
}

module.exports = {
  initProject
};
